import cv2,json,numpy as np
from pathlib import Path
R=Path('/home/coder/share/drawer-stable-cohort-20260912');C=json.loads(Path('/home/coder/share/drawer-uniform-dataset-20260912/final-config.json').read_text());rows=json.loads((R/'clear-marker.json').read_text());ordered=sorted([x for x in rows if (x['max_pixels'] or 0)>=3],key=lambda x:x['p90_pixels'] or 0,reverse=True);panels=[]
